// 1. Jurin's Law: capillary equilibrium height
val equilibriumHeightM = (2f * gammaNPerM * cosTheta) / max(densityKgM3 * g * radiusM, 1e-8f)
val currentHeightMm = equilibriumHeightM * 1000f * climbProgress

// 2. Young-Laplace pressure jump across curved meniscus
val laplacePressurePa = (2f * gammaNPerM * cosTheta) / max(radiusM, 1e-6f)
val deltaPressureKPa = laplacePressurePa / 1000f

// 3. Vertical capillary force balancing gravitational column weight
val capillaryForceN = 2f * PI.toFloat() * radiusM * gammaNPerM * cosTheta
val capillaryForceMicroN = capillaryForceN * 1_000_000f
